import { USERS, expect, test, uniqueName } from "../../fixtures";

test("Update a draft vendor", { tag: "@VEN-08" }, async ({ apiAs }) => {
  const member = await apiAs("member");

  // Given a vendor in status "draft"
  const created = await member.post("/api/vendors", {
    data: { name: uniqueName("Acme Freight"), category: "logistics", contact_email: "ops@acmefreight.example" },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();
  expect(vendor.status).toBe("draft");

  // When I change its contact email
  const res = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { contact_email: "billing@acmefreight.example" },
  });

  // Then the response status is 200
  expect(res.status(), await res.text()).toBe(200);
  const updated = await res.json();
  expect(updated.id).toBe(vendor.id);
  expect(updated.contact_email).toBe("billing@acmefreight.example");
  expect(updated.status).toBe("draft");

  // And an audit event "vendor.updated" is recorded
  await expect
    .poll(
      async () => {
        const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
        expect(audit.status(), await audit.text()).toBe(200);
        const body = await audit.json();
        return (body.items as Array<{ action: string }>).map((e) => e.action);
      },
      { message: "audit trail should contain vendor.updated" },
    )
    .toContain("vendor.updated");

  const audit = await member.get(`/api/vendors/${vendor.id}/audit`);
  expect(audit.status(), await audit.text()).toBe(200);
  const events = (await audit.json()).items as Array<{ action: string; actor: { email: string } }>;
  const updatedEvent = events.find((e) => e.action === "vendor.updated");
  expect(updatedEvent?.actor.email).toBe(USERS.member);
});
